// apex-psi-mcp — the hosted door. Same five tools as `npx apex-psi-mcp`, over
// Streamable HTTP, asking for nothing.
//
// Why this exists next to the stdio package: an agent that is not a person with a
// laptop cannot run `npx`. Every hosted MCP directory, every browser-side client
// and most agent frameworks want one URL. Until now the only URL we had was
// /functions/v1/mcp, and that file is generated by @lovable.dev/mcp-js with
// `auth.oauth.issuer(...)` configured, so it answers a caller with no Supabase
// session 401 {"error":"unauthorized"} — measured 18 Nov 2026, both projects, POST
// initialize. Its own code path does run unauthenticated (GET answers 405 and
// OPTIONS 204), so the lock is the library's OAuth setting, not the gateway.
//
// This function is a second, deliberately unauthenticated surface. It is not a
// replacement for /mcp, and it must not be confused with it: the generated file
// belongs to the Lovable plugin and will be rewritten by it.
//
// The address is the product name, so a client config reads like a citation:
//   https://<project>.supabase.co/functions/v1/apex-psi-mcp

import { handleApexMcp } from "./handler.ts";

// Announced version. Kept in step with the npm package whose tool table this
// copies; scripts/hosted-mcp-check.mjs fails if the two surfaces disagree on the
// five names, and the MCP repo's own card guard fails if the registry card drifts.
const VERSION = "1.2.2";

const env = (name: string, fallback: string) => (Deno.env.get(name) || "").trim() || fallback;

const SUPABASE_URL = (Deno.env.get("SUPABASE_URL") || "").trim().replace(/\/+$/, "");
const CONFIG = {
  apiBase: (Deno.env.get("APEX_API_BASE") || "").trim().replace(/\/+$/, "")
    || (SUPABASE_URL ? `${SUPABASE_URL}/functions/v1` : "https://qhtntebpcribjiwrdtdd.supabase.co/functions/v1"),
  siteBase: (Deno.env.get("SITE_URL") || "https://www.ai-governance-standard.com").replace(/\/+$/, ""),
  version: VERSION,
  fetch,
};

Deno.serve((req) => handleApexMcp(req, CONFIG));
